// Відповідь Tavily
const tavily = $input.first().json;
// Вхідні дані з форми беремо прямо з вузла Webhook
const body = $('Webhook').first().json.body;

// Залишаємо лише релевантні результати і тільки потрібні поля
const sources = (tavily.results || [])
  .filter(r => r.score >= 0.1)
  .map(r => ({
    title: r.title,
    url: r.url,
    content: (r.content || '').replace(/\s+/g, ' ').slice(0, 600),
  }));

return [{
  json: {
    idea: body.idea,
    market: body.market,
    search_answer: tavily.answer || '',
    sources,
  },
}];
